const updateObservedRun = `-- name: UpdateObservedRun :one
UPDATE machine_runs SET
    vendor_job_id=COALESCE(vendor_job_id, $1::text),
    state=CASE
        WHEN state IN ('finished','failed','cancelled') THEN state
        WHEN $2::timestamptz >= last_observed_at THEN $3::text
        ELSE state
    END,
    history_complete=history_complete AND $4::boolean,
    last_observed_at=GREATEST(last_observed_at, $2::timestamptz),
    version=version + CASE
        WHEN $2::timestamptz > last_observed_at THEN 1
        ELSE 0
    END,
    updated_at=CASE
        WHEN $2::timestamptz > last_observed_at THEN now()
        ELSE updated_at
    END
WHERE id=$5 AND assignment_id=$6 AND machine_id=$7
RETURNING id, assignment_id, machine_id, vendor_job_id, state, history_complete, first_observed_at, last_observed_at, version, created_at, updated_at, display_id, file_name, started_at, ended_at, estimated_end_at, progress_percent, reported_quantity_g, reported_quantity_basis, reported_spool_id, reported_event_id, source, job_id, outcome, artifact_id, deleted_at, deleted_by, hidden_from_signage, artifact_manual
`

